import{_ as e,o as i,c as l,a3 as o}from"./chunks/framework.Dj4Lt7vj.js";const p=JSON.parse('{"title":"管理 AI 方案","description":"","frontmatter":{"title":"管理 AI 方案"},"headers":[],"relativePath":"workspace/solutions.md","filePath":"workspace/solutions.md","lastUpdated":1787948622000}'),t={name:"workspace/solutions.md"};function r(s,a,n,h,d,c){return i(),l("div",null,[...a[0]||(a[0]=[o('<h1 id="管理-ai-方案" tabindex="-1">管理 AI 方案 <a class="header-anchor" href="#管理-ai-方案" aria-label="Permalink to &quot;管理 AI 方案&quot;">​</a></h1><p>工作台的「AI方案」标签页可以在浏览器里查看和调整 AI 方案，不必回到接待电脑。</p><h2 id="能做什么" tabindex="-1">能做什么 <a class="header-anchor" href="#能做什么" aria-label="Permalink to &quot;能做什么&quot;">​</a></h2><ul><li>查看账号下的所有方案，以及每个方案绑定了哪些店铺。</li><li>编辑方案的回复设定：角色说明、回复要求。</li><li>管理方案下的接待角色（客户端里叫「情景」）：每个角色负责一类问题，可以查看它的触发条件数量和专属资料数量。</li><li>调整方案绑定的知识库。</li></ul><p>方案的完整编辑能力（八个配置模块）在桌面客户端里，见<a href="/aicare-docs/solution/editor">方案编辑器</a>。工作台侧重日常微调：改话术、调资料、开关角色。</p><h2 id="常见操作" tabindex="-1">常见操作 <a class="header-anchor" href="#常见操作" aria-label="Permalink to &quot;常见操作&quot;">​</a></h2><h3 id="修改回复话术" tabindex="-1">修改回复话术 <a class="header-anchor" href="#修改回复话术" aria-label="Permalink to &quot;修改回复话术&quot;">​</a></h3><ol><li>打开「AI方案」标签页，选中要改的方案。</li><li>找到对应的接待角色，编辑它的回复设定。</li><li>保存后新会话立即按新设定执行，接待电脑上不需要任何操作。</li></ol><h3 id="检查角色状态" tabindex="-1">检查角色状态 <a class="header-anchor" href="#检查角色状态" aria-label="Permalink to &quot;检查角色状态&quot;">​</a></h3><p>每个接待角色卡片上能看到：状态（已开启 / 未开启）、是否默认接待、负责问题数（触发条件数量）、专属资料数。</p><ul><li><strong>默认接待</strong>角色兜底处理没有命中任何触发条件的消息，每个方案有且只有一个。</li><li>未开启的角色即使命中触发条件也会被跳过。</li></ul><h3 id="配合运营助手" tabindex="-1">配合运营助手 <a class="header-anchor" href="#配合运营助手" aria-label="Permalink to &quot;配合运营助手&quot;">​</a></h3><p>不确定该改哪里时，先去「运营助手」标签页把诉求说出来，比如「顾客问发货时间时回答得太啰嗦」。助手会定位相关配置并给出修改建议，你确认后生效。</p><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="/aicare-docs/solution/editor">方案编辑器</a></li><li><a href="/aicare-docs/solution/agents">AI 设置与智能程度</a></li><li><a href="/aicare-docs/solution/triggers">情景与触发规则</a></li></ul>',15)])])}const _=e(t,[["render",r]]);export{p as __pageData,_ as default};
